import{_ as a,a as r,b as i,c as e,d as o,e as s,f as n,g as d,h as l,i as h,j as c}from"./chunks/chat-import-07.B7k0d_Ex.js";import{_ as g,o as p,c as f,a3 as u}from"./chunks/framework.D1iekJsc.js";const y=JSON.parse('{"title":"聊天存档","description":"MiniTavern 单聊存档：导出 ZIP、从列表或文件导入；合并到已有聊天或作为新聊天。","frontmatter":{"title":"聊天存档","description":"MiniTavern 单聊存档：导出 ZIP、从列表或文件导入；合并到已有聊天或作为新聊天。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"聊天存档 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 单聊存档：导出 ZIP、从列表或文件导入；合并到已有聊天或作为新聊天。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/chat-archive"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/chat-archive"}]]},"headers":[],"relativePath":"manual/chat-archive.md","filePath":"manual/chat-archive.md","lastUpdated":1787816217000}'),m={name:"manual/chat-archive.md"};function b(_,t,v,T,I,P){return p(),f("div",null,[...t[0]||(t[0]=[u('<h1 id="聊天存档" tabindex="-1">聊天存档 <a class="header-anchor" href="#聊天存档" aria-label="Permalink to &quot;聊天存档&quot;">​</a></h1><p>聊天存档是<strong>单个会话</strong>的 ZIP 包，用来备份长线剧情、换机带走或分享给他人。与 <a href="./backup">全量备份</a>（全量 ZIP）不同，请勿混用恢复入口。</p><p>路径：<strong>设置 → 数据管理 → 聊天存档</strong>（管理已保存的存档文件）。</p><h2 id="导出-创建存档" tabindex="-1">导出（创建存档） <a class="header-anchor" href="#导出-创建存档" aria-label="Permalink to &quot;导出（创建存档）&quot;">​</a></h2><p>导出会打包当前会话的消息、会话配置与相关本地资源，完成后写入 App 内「聊天存档」列表，也可在进度结束后分享 ZIP。</p><h3 id="会话列表-·-三点菜单" tabindex="-1">会话列表 · 三点菜单 <a class="header-anchor" href="#会话列表-·-三点菜单" aria-label="Permalink to &quot;会话列表 · 三点菜单&quot;">​</a></h3><p>在 <strong>聊天</strong> Tab 的会话卡片上点 <strong>⋯</strong>（操作菜单）→ <strong>存档</strong>。</p><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="三点菜单"><figcaption>1 · 点击操作</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="存档"><figcaption>2 · 选择存档</figcaption></figure></div><h3 id="聊天设置-·-底部按钮" tabindex="-1">聊天设置 · 底部按钮 <a class="header-anchor" href="#聊天设置-·-底部按钮" aria-label="Permalink to &quot;聊天设置 · 底部按钮&quot;">​</a></h3><p>对话页 → <strong>聊天设置</strong> → 滚动到底部，点 <strong>存档</strong>（与「重新开始」并排）。</p><div class="shot-flow"><figure class="shot-step"><img src="'+i+'" alt="聊天设置底部"><figcaption>1 · 聊天页点击设置</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="存档按钮"><figcaption>2 · 选择存档</figcaption></figure></div><h3 id="聊天存档列表-·-创建存档" tabindex="-1">聊天存档列表 · 创建存档 <a class="header-anchor" href="#聊天存档列表-·-创建存档" aria-label="Permalink to &quot;聊天存档列表 · 创建存档&quot;">​</a></h3><p><strong>设置 → 数据管理 → 聊天存档</strong> → 右上角 <strong>+</strong> → <strong>创建存档</strong> → 选择要导出的会话（流程与上相同）。</p><h2 id="导入" tabindex="-1">导入 <a class="header-anchor" href="#导入" aria-label="Permalink to &quot;导入&quot;">​</a></h2><p>导入前会校验文件是否为聊天存档；若选成全量备份或无效文件，进度弹窗会提示错误并退出。</p><p>若本机已存在<strong>同一聊天</strong>（相同会话 ID），会弹出方式选择：</p><p><img src="'+o+'" alt="合并或作为新聊天"></p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>合并到已有聊天</strong></td><td>将存档内容并入已存在的会话，较新数据覆盖较旧</td></tr><tr><td><strong>作为新聊天导入</strong></td><td>保留当前聊天，存档另开一条新会话</td></tr></tbody></table><h3 id="聊天-tab-·-导航栏右侧" tabindex="-1">聊天 Tab · 导航栏右侧 <a class="header-anchor" href="#聊天-tab-·-导航栏右侧" aria-label="Permalink to &quot;聊天 Tab · 导航栏右侧&quot;">​</a></h3><p><strong>聊天</strong> Tab 右上角 <strong>+</strong>：</p><table tabindex="0"><thead><tr><th>菜单项</th><th>行为</th></tr></thead><tbody><tr><td><strong>从存档导入</strong></td><td>从 App 内已保存的聊天存档列表中选一条导入</td></tr><tr><td><strong>从文件导入</strong></td><td>用系统文件选择器选外部 ZIP，校验后进入上述导入流程</td></tr></tbody></table><p>列表内暂无存档时选「从存档导入」会提示先去导出。</p><div class="shot-flow"><figure class="shot-step"><img src="'+s+'" alt="聊天 Tab 加号"><figcaption>1 · 聊天 Tab · +</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="从存档或文件导入"><figcaption>2 · 从存档 / 从文件导入</figcaption></figure></div><h3 id="聊天存档列表" tabindex="-1">聊天存档列表 <a class="header-anchor" href="#聊天存档列表" aria-label="Permalink to &quot;聊天存档列表&quot;">​</a></h3><p><strong>设置 → 数据管理 → 聊天存档</strong>：</p><table tabindex="0"><thead><tr><th>入口</th><th>行为</th></tr></thead><tbody><tr><td>右上角 <strong>+</strong> → <strong>从文件导入</strong></td><td>与聊天 Tab「从文件导入」相同</td></tr><tr><td>某条存档右侧菜单 → <strong>导入</strong></td><td>直接导入该条已保存的存档</td></tr></tbody></table><div class="shot-flow"><figure class="shot-step"><img src="'+d+'" alt="聊天存档列表"><figcaption>1 · 设置页选择存档与备份</figcaption></figure><figure class="shot-step"><img src="'+l+'" alt="列表导入入口"><figcaption>2 · 选择聊天存档</figcaption></figure><figure class="shot-step"><img src="'+h+'" alt="导入存档"><figcaption>3 · 点击操作</figcaption></figure><figure class="shot-step"><img src="'+c+'" alt="存档列表操作"><figcaption>4 · 导入/分享 / 管理存档</figcaption></figure></div><p>列表内还可 <strong>分享</strong>、重命名、置顶、删除存档文件（删除不可恢复）。</p><h2 id="与全量备份的区别" tabindex="-1">与全量备份的区别 <a class="header-anchor" href="#与全量备份的区别" aria-label="Permalink to &quot;与全量备份的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>聊天存档</th><th>全量备份</th></tr></thead><tbody><tr><td>范围</td><td>单个会话</td><td>角色、全部聊天、世界书等</td></tr><tr><td>格式</td><td>单聊 ZIP</td><td>全量 ZIP</td></tr><tr><td>恢复入口</td><td>聊天 Tab / 聊天存档列表</td><td>设置 → 数据管理 → 备份恢复</td></tr></tbody></table><p>全量备份说明见 <a href="./backup">备份与存档</a>。</p><h2 id="出错时" tabindex="-1">出错时 <a class="header-anchor" href="#出错时" aria-label="Permalink to &quot;出错时&quot;">​</a></h2><p>导入/导出失败可查看进度弹窗或 Toast 提示；常见原因包括文件类型错误、磁盘空间不足。气泡级错误对照 <a href="./errors">错误代码排错</a>。</p>',33)])])}const x=g(m,[["render",b]]);export{y as __pageData,x as default};
